import {
  Play, Pause, RotateCcw, Shuffle, Users, ListOrdered, Sparkles,
  Users2, Plus, Minus, Save, X, Pencil, Trophy, Loader2,
  Ghost, Skull, KeyRound, Settings2, Delete, PartyPopper, ArrowRight
} from "lucide-react";

